"use client";
import { Suspense, useEffect, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { setCookie, getCookie } from "cookies-next";
import { adminLoginAction } from "@/app/actions/auth";
import { primaryRole } from "@/lib/role";
import { ApiError } from "@/lib/apiClient";
import postResetPassword from "@/services/auth/resetPasswordService";
import postSignUp from "@/services/auth/signUpService";

const GOOGLE_CLIENT_ID = "173591342442-bjferec6evjg4ggpgec0vdc31shiq5uu.apps.googleusercontent.com";
const FB_APP_ID = process.env.NEXT_PUBLIC_FACEBOOK_APP_ID ?? "";

const inputCls = "tw-w-full tw-px-3.5 tw-py-3 tw-rounded-[10px] tw-text-[16px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid tw-border-[#d8d2e1] focus:tw-border-[#854ec9] placeholder:tw-text-[#8a8398] disabled:tw-opacity-50 tw-bg-white";
const labelCls = "tw-text-[13px] tw-font-semibold tw-text-[#2a2336]";
const submitCls = "tw-w-full tw-mt-2 tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-px-[22px] tw-py-3.5 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[15px] tw-font-semibold tw-border-0 tw-cursor-pointer disabled:tw-opacity-60 tw-transition-colors";

function SocialButtons({ returnTo }: { returnTo: string }) {
  const handleSocialLogin = (provider: "google" | "facebook") => {
    const base = `${window.location.origin}/auth/callback`;
    const state = encodeURIComponent(returnTo || window.location.href);
    if (provider === "google") {
      const p = new URLSearchParams({
        client_id: GOOGLE_CLIENT_ID,
        redirect_uri: `${base}?p=g`,
        response_type: "code",
        scope: "openid email profile",
        state,
        access_type: "online",
      });
      window.location.href = `https://accounts.google.com/o/oauth2/v2/auth?${p}`;
    } else {
      const p = new URLSearchParams({
        client_id: FB_APP_ID,
        redirect_uri: `${base}?p=f`,
        scope: "email,public_profile",
        state,
      });
      window.location.href = `https://www.facebook.com/v18.0/dialog/oauth?${p}`;
    }
  };

  return (
    <div className="tw-flex tw-flex-col tw-gap-2.5">
      <button type="button" onClick={() => handleSocialLogin("google")}
        className="tw-w-full tw-flex tw-items-center tw-justify-center tw-gap-2.5 tw-p-3 tw-border tw-border-solid tw-border-[#d8d2e1] tw-bg-white tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-cursor-pointer hover:tw-border-[#14101c] hover:tw-bg-[#faf9fc] tw-rounded-[12px] tw-transition-colors">
        <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
          <path d="M17.64 9.2c0-.637-.057-1.251-.164-1.84H9v3.481h4.844c-.209 1.125-.843 2.078-1.796 2.717v2.258h2.908c1.702-1.567 2.684-3.875 2.684-6.615z" fill="#4285F4"/>
          <path d="M9.003 18c2.43 0 4.467-.806 5.956-2.184L12.05 13.56c-.806.54-1.836.86-3.047.86-2.344 0-4.328-1.584-5.036-3.711H.96v2.332C2.438 15.983 5.482 18 9.003 18z" fill="#34A853"/>
          <path d="M3.964 10.712c-.18-.54-.282-1.117-.282-1.71 0-.593.102-1.17.282-1.71V4.96H.957C.347 6.175 0 7.55 0 9.002c0 1.452.348 2.827.957 4.042l3.007-2.332z" fill="#FBBC05"/>
          <path d="M9.003 3.58c1.321 0 2.508.454 3.44 1.345l2.582-2.58C13.464.891 11.426 0 9.003 0 5.482 0 2.438 2.017.96 4.958L3.967 7.29c.708-2.127 2.692-3.71 5.036-3.71z" fill="#EA4335"/>
        </svg>
        Continue with Google
      </button>
      <button type="button" onClick={() => handleSocialLogin("facebook")}
        className="tw-w-full tw-flex tw-items-center tw-justify-center tw-gap-2.5 tw-p-3 tw-border tw-border-solid tw-border-[#d8d2e1] tw-bg-white tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-cursor-pointer hover:tw-border-[#14101c] hover:tw-bg-[#faf9fc] tw-rounded-[12px] tw-transition-colors">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="#1877F2">
          <path d="M24 12.073C24 5.405 18.627 0 12 0S0 5.405 0 12.073C0 18.1 4.388 23.094 10.125 24v-8.437H7.078v-3.49h3.047V9.41c0-3.025 1.792-4.697 4.533-4.697 1.312 0 2.686.235 2.686.235v2.97h-1.513c-1.491 0-1.956.93-1.956 1.886v2.268h3.328l-.532 3.49h-2.796V24C19.612 23.094 24 18.1 24 12.073z"/>
        </svg>
        Continue with Facebook
      </button>
    </div>
  );
}

function LoginPageContent() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const returnTo = searchParams.get("returnTo") || "/";
  const initialError = searchParams.get("error") || "";

  useEffect(() => {
    if (getCookie("auth-token")) router.replace(returnTo);
  }, []);

  const [mode, setMode] = useState<"login" | "forgot" | "register">("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [reg, setReg] = useState({ firstName: "", lastName: "", phone: "", passwordAgain: "" });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(initialError);
  const [success, setSuccess] = useState("");

  const switchMode = (m: typeof mode) => { setError(""); setSuccess(""); setMode(m); };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(""); setSuccess("");

    if (mode === "login") {
      setLoading(true);
      try {
        // The login request to /api/v1/administrator/login runs on the SERVER
        // (server action), so the API URL stays out of the browser.
        const res = await adminLoginAction(email.trim(), password);
        if (res.ok) {
          const maxAge = 60 * 60 * 24 * 365;
          setCookie("user-email", res.user.email, { maxAge });
          setCookie("user-avatar", "", { maxAge });
          setCookie("user-full-name", res.user.name, { maxAge });
          setCookie("user-id", res.user.id, { maxAge });
          setCookie("user-role", res.user.role, { maxAge });
          window.location.href = returnTo || "/";
        } else {
          setError(
            res.reason === "unreachable"
              ? "Cannot reach the server. Please try again in a moment."
              : res.reason === "invalid"
                ? "Invalid email or password."
                : res.message,
          );
          setLoading(false);
        }
      } catch {
        setError("Something went wrong. Please try again.");
        setLoading(false);
      }

    } else if (mode === "forgot") {
      setLoading(true);
      try {
        await postResetPassword({ email });
        setSuccess("Password reset email sent. Please check your inbox.");
      } catch {
        setError("Invalid email address.");
      }
      setLoading(false);

    } else {
      if (password !== reg.passwordAgain) { setError("Passwords do not match."); return; }
      if (password.length < 6) { setError("Password must be at least 6 characters."); return; }
      setLoading(true);
      try {
        // apiv3 /auth/register returns the same contract as login: { token (Sanctum),
        // token_old (api_token), user }. Two tokens: api_token -> legacy api + apiv2,
        // Sanctum -> apiv3. On 422 apiClient throws ApiError.
        const res = await postSignUp({
          requestData: { email, password, phone: reg.phone, firstName: reg.firstName, lastName: reg.lastName },
        });
        const maxAge = 60 * 60 * 24 * 365;
        setCookie("auth-token", res.token_old, { maxAge });
        setCookie("auth-token-v3", res.token, { maxAge });
        setCookie("user-email", res.user.email, { maxAge });
        setCookie("user-avatar", res.user.avatar ?? "", { maxAge });
        setCookie("user-full-name", res.user.name, { maxAge });
        setCookie("user-id", res.user.id.toString(), { maxAge });
        setCookie("user-role", primaryRole(res.user.roles), { maxAge });
        window.location.href = returnTo || "/";
      } catch (err) {
        if (err instanceof ApiError && err.errors) {
          const firstKey = Object.keys(err.errors)[0];
          setError(firstKey ? err.errors[firstKey][0] : "Registration failed.");
        } else {
          setError("This email or phone is already registered.");
        }
        setLoading(false);
      }
    }
  };

  return (
    <div className="tw-min-h-screen tw-flex tw-items-center tw-justify-center tw-pb-12 tw-px-4" style={{ background: "#faf9fc" }}>
      <div className="tw-w-full tw-max-w-[440px]">
        <div className="tw-bg-white tw-rounded-[20px] tw-p-8" style={{ boxShadow: "0 4px 24px rgba(20,16,28,0.08)" }}>
          {mode === "login" && (
            <>
              <h1 className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-1 tw-mt-0" style={{ letterSpacing: "-0.02em" }}>Welcome back</h1>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-mb-6 tw-mt-0">Sign in to your TravelShop Booking account</p>

              {error && <div className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]" style={{ background: "rgba(239,68,68,0.08)" }}>{error}</div>}

              <form onSubmit={handleSubmit} className="tw-flex tw-flex-col tw-gap-4">
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label className={labelCls}>Email</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)}
                    placeholder="Enter your email address" required disabled={loading} className={inputCls} />
                </div>
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label className={labelCls}>Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••" required disabled={loading} className={inputCls} />
                </div>
                <div className="tw-text-right tw--mt-2">
                  <button type="button" onClick={() => switchMode("forgot")}
                    className="tw-text-[13px] tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline">
                    Forgot password?
                  </button>
                </div>
                <button type="submit" disabled={loading} className={submitCls}>
                  {loading ? <><span className="tw-inline-block tw-w-4 tw-h-4 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]" role="status" aria-hidden="true" /> Signing in…</> : "Sign in"}
                </button>
              </form>

              <div className="tw-relative tw-text-center tw-my-5">
                <span className="tw-absolute tw-left-0 tw-right-0 tw-h-px tw-bg-[#ebe7f0]" style={{ top: "50%" }} aria-hidden="true" />
                <span className="tw-relative tw-inline-block tw-bg-white tw-px-3 tw-text-[13px] tw-text-[#5d556c] tw-font-medium">or</span>
              </div>

              <SocialButtons returnTo={returnTo} />

              <div className="tw-text-center tw-text-[14px] tw-text-[#5d556c] tw-mt-5">
                Don&apos;t have an account?{" "}
                <button type="button" onClick={() => switchMode("register")}
                  className="tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline">
                  Create one
                </button>
              </div>
            </>
          )}

          {mode === "forgot" && (
            <>
              <h1 className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-1 tw-mt-0" style={{ letterSpacing: "-0.02em" }}>Reset your password</h1>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-mb-6 tw-mt-0">We&apos;ll send you a link to reset your password.</p>

              {error && <div className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]" style={{ background: "rgba(239,68,68,0.08)" }}>{error}</div>}
              {success && <div className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#15803d]" style={{ background: "rgba(22,163,74,0.08)" }}>{success}</div>}

              <form onSubmit={handleSubmit} className="tw-flex tw-flex-col tw-gap-4">
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label className={labelCls}>Email</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)}
                    placeholder="Enter your email address" required disabled={loading || !!success} className={inputCls} />
                </div>
                {!success && (
                  <button type="submit" disabled={loading} className={submitCls}>
                    {loading ? <><span className="tw-inline-block tw-w-4 tw-h-4 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]" role="status" aria-hidden="true" /> Sending…</> : "Send reset link"}
                  </button>
                )}
              </form>
              <div className="tw-mt-4 tw-text-center">
                <button onClick={() => switchMode("login")} type="button"
                  className="tw-text-[14px] tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline">
                  ← Back to sign in
                </button>
              </div>
            </>
          )}

          {mode === "register" && (
            <>
              <h1 className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-1 tw-mt-0" style={{ letterSpacing: "-0.02em" }}>Create an account</h1>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-mb-6 tw-mt-0">Join TravelShop Booking and start exploring the world.</p>

              {error && <div className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]" style={{ background: "rgba(239,68,68,0.08)" }}>{error}</div>}

              <form onSubmit={handleSubmit} className="tw-flex tw-flex-col tw-gap-4">
                <div className="tw-grid tw-gap-4" style={{ gridTemplateColumns: "1fr 1fr" }}>
                  <div className="tw-flex tw-flex-col tw-gap-1.5">
                    <label className={labelCls}>First name</label>
                    <input type="text" value={reg.firstName} onChange={(e) => setReg({ ...reg, firstName: e.target.value })}
                      placeholder="First name" required disabled={loading} className={inputCls} />
                  </div>
                  <div className="tw-flex tw-flex-col tw-gap-1.5">
                    <label className={labelCls}>Last name</label>
                    <input type="text" value={reg.lastName} onChange={(e) => setReg({ ...reg, lastName: e.target.value })}
                      placeholder="Last name" required disabled={loading} className={inputCls} />
                  </div>
                </div>
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label className={labelCls}>Email</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)}
                    placeholder="Enter your email address" required disabled={loading} className={inputCls} />
                </div>
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label className={labelCls}>Phone</label>
                  <input type="tel" value={reg.phone} onChange={(e) => setReg({ ...reg, phone: e.target.value })}
                    placeholder="+1 234 567 8900" required disabled={loading} className={inputCls} />
                </div>
                <div className="tw-grid tw-gap-4" style={{ gridTemplateColumns: "1fr 1fr" }}>
                  <div className="tw-flex tw-flex-col tw-gap-1.5">
                    <label className={labelCls}>Password</label>
                    <input type="password" value={password} onChange={(e) => setPassword(e.target.value)}
                      placeholder="••••••••" required autoComplete="new-password" disabled={loading} className={inputCls} />
                  </div>
                  <div className="tw-flex tw-flex-col tw-gap-1.5">
                    <label className={labelCls}>Confirm</label>
                    <input type="password" value={reg.passwordAgain} onChange={(e) => setReg({ ...reg, passwordAgain: e.target.value })}
                      placeholder="••••••••" required disabled={loading} className={inputCls} />
                  </div>
                </div>
                <button type="submit" disabled={loading} className={submitCls}>
                  {loading ? <><span className="tw-inline-block tw-w-4 tw-h-4 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]" role="status" aria-hidden="true" /> Creating account…</> : "Create account"}
                </button>
              </form>
              <div className="tw-mt-4 tw-text-center tw-text-[14px] tw-text-[#5d556c]">
                Already have an account?{" "}
                <button type="button" onClick={() => switchMode("login")}
                  className="tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline">
                  Sign in
                </button>
              </div>
            </>
          )}
        </div>

        <div className="tw-text-center tw-mt-6">
          <a href="/" className="tw-text-[13px] tw-text-[#5d556c] tw-no-underline hover:tw-text-[#14101c]">← Back to home</a>
        </div>
      </div>
    </div>
  );
}

export default function LoginPage() {
  return (
    <Suspense fallback={
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div className="tw-inline-block tw-w-9 tw-h-9 tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent tw-animate-spin" role="status" />
      </div>
    }>
      <LoginPageContent />
    </Suspense>
  );
}